import{_ as t,c as a,o as r,ag as i}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Research Citations","description":"","frontmatter":{"title":"Research Citations"},"headers":[],"relativePath":"research/research-citations.md","filePath":"research/research-citations.md","lastUpdated":null}'),o={name:"research/research-citations.md"};function n(s,e,l,c,h,d){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="research-citations" tabindex="-1">Research Citations <a class="header-anchor" href="#research-citations" aria-label="Permalink to &quot;Research Citations&quot;">​</a></h1><h2 id="citations" tabindex="-1">Citations <a class="header-anchor" href="#citations" aria-label="Permalink to &quot;Citations&quot;">​</a></h2><p>This page provides useful resources and tools for managing citations in your work, along with best practices and why citations are essential for building trust and credibility.</p><h3 id="citation-resources" tabindex="-1">Citation Resources <a class="header-anchor" href="#citation-resources" aria-label="Permalink to &quot;Citation Resources&quot;">​</a></h3><p>The following resources will help you generate and format citations correctly for your research:</p><ul><li><p><a href="https://libguides.nps.edu/citation/apa" target="_blank" rel="noreferrer">NPS Citation Guide</a> – This guide includes citations for intelligence, operational, and administrative documents, providing an APA format reference.</p></li><li><p><a href="https://u.pcloud.link/publink/show?code=XZabevVZW2084cBks6mGq0g6GRF4BfipdlfX" target="_blank" rel="noreferrer">APA Student Template</a> – A Word document template designed to help students format their citations properly.</p></li><li><p><a href="https://zbib.org/" target="_blank" rel="noreferrer">ZBib</a> – A free and simple citation generator that can be used to create various citation styles.</p></li><li><p><a href="https://www.citationmachine.net/apa" target="_blank" rel="noreferrer">Citation Machine</a> – Another online tool that helps generate citations quickly in multiple styles, including APA.</p></li></ul><h3 id="reference-management" tabindex="-1">Reference Management <a class="header-anchor" href="#reference-management" aria-label="Permalink to &quot;Reference Management&quot;">​</a></h3><p>Here are tools and services designed for managing references and ensuring you can retrieve cited content even if the original source changes or is removed:</p><ul><li><p><strong><a href="https://www.zotero.org/" target="_blank" rel="noreferrer">Zotero</a></strong> – A popular reference manager that allows you to store, organize, and generate citations.</p></li><li><p><strong><a href="https://www.vortimo.com/features/" target="_blank" rel="noreferrer">Vortimo</a></strong> – A tool that automatically saves all web pages you visit locally on your hard drive as they appear in your browser. Great for storing research and sources that may not be available later.</p><ul><li><a href="https://www.vortimo.com/contact-us/" target="_blank" rel="noreferrer">Message Vortimo</a> – If you are a student, Vortimo may offer you a free license for their tool.</li></ul></li><li><p><strong><a href="https://www.httrack.com/" target="_blank" rel="noreferrer">HTTrack</a></strong> – A tool for copying and saving entire websites exactly as they appear. This is useful for ensuring your sources are preserved in case of future changes.</p><ul><li><strong><a href="https://blog.archive.org/2017/01/25/see-something-save-something/" target="_blank" rel="noreferrer">Submit a page for archive</a></strong> – You can submit pages to be archived on the Internet Archive, allowing future access to important references.</li></ul></li></ul><h3 id="the-importance-of-citations" tabindex="-1">The Importance of Citations <a class="header-anchor" href="#the-importance-of-citations" aria-label="Permalink to &quot;The Importance of Citations&quot;">​</a></h3><p>Citations are crucial for several significant reasons:</p><ol><li><p><strong>Trust and Credibility</strong> — Properly citing sources demonstrates thorough research and provides factual support for your statements. This transparency builds trust with readers, enabling them to verify the accuracy of your work and rely confidently upon your research.</p></li><li><p><strong>Knowledge Management</strong> — Citations contribute to the collective body of knowledge by explicitly documenting sources and references. This enables future researchers and teams to trace the origin of findings, expand upon existing research, and prevent the inadvertent loss of critical information.</p></li><li><p><strong>Collaboration and Continuous Improvement</strong> — By clearly citing sources, research can effectively become a living document that evolves through continuous collaboration. Future researchers and other teams can easily access primary sources, identify gaps, and make informed decisions about areas that require further investigation or modification.</p></li><li><p><strong>Lateral Research and Contextual Understanding</strong> — Storing and citing sources also enhances lateral research capabilities. Researchers and teams can efficiently identify primary and adjacent content, facilitating a deeper and broader understanding of the research topic. This approach allows exploration of related or tangential areas that may provide additional insights or alternative perspectives.</p></li></ol><p>For more details on the necessity and benefits of citations, refer to <a href="https://nps.edu/web/gwc/why-cite-a-writer-s-perspective" target="_blank" rel="noreferrer">Why Cite: A Writer&#39;s Perspective</a>.</p><h3 id="what-needs-to-be-cited" tabindex="-1">What Needs to Be Cited? <a class="header-anchor" href="#what-needs-to-be-cited" aria-label="Permalink to &quot;What Needs to Be Cited?&quot;">​</a></h3><p>Not all information requires citation; distinguishing between common knowledge and content requiring documentation is essential. Generally:</p><ul><li><p><strong>Common Knowledge</strong> — Facts that are widely known and readily available in multiple reliable sources do not typically require citation.</p></li><li><p><strong>Specific Data or Unique Ideas</strong> — Direct quotations, statistics, specialized concepts, and specific claims not universally recognized must be cited.</p></li></ul><p>For further clarification, consult the <a href="https://nps.edu/documents/111693070/112854156/Common+Knowledge+Infographic.pdf/707ffba8-f8cc-8310-561d-9c146604ab9c?t=1617640088652" target="_blank" rel="noreferrer">NPS Common Knowledge PDF</a>.</p><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3>',18)])])}const f=t(o,[["render",n]]);export{p as __pageData,f as default};
